-- No question content or account data.
SELECT (EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.save_question_bank_drafts(jsonb)') AND md5(replace(prosrc,E'\r',''))='b91a6d0727db33c241eea21af1099890') AND EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.update_question_bank_draft_metadata(uuid,uuid,text,jsonb)') AND md5(replace(prosrc,E'\r',''))='a412f52367bbca42c051f2ccfea53921') AND EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.question_bank_content_issues(uuid,uuid)') AND md5(replace(prosrc,E'\r',''))='f4031a1b17ae40a0a7e94662012a0934')) AS known_functions_match,(NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261105020000') AND to_regprocedure('public.question_bank_legacy_arena_source(jsonb,text)') IS NULL) AS target_absent,to_regclass('public.arena_questions') IS NOT NULL AS legacy_table_present;
